                for (int j = 0; j < m; j++) {
                    double diff = train[i][j] - cents[c][j];
                    d += diff * diff;
                }
                d = std::sqrt(d);
                if (d < minDist) {
                    minDist = d;
                    best = c;
                }
            }
            labels[i] = best;
